import{z as n,x as E,o as c,c as p,q as s,j as i,D as a,d as o,s as l,S as t,b as d}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"伪指令","description":"","frontmatter":{"title":"伪指令","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pseudo-instructions.md","filePath":"cs/pseudo-instructions.md","lastUpdated":1791063341000}'),A={name:"cs/pseudo-instructions.md"};function B(u,e,m,C,h,D){const r=E("Mermaid");return c(),p("div",null,[e[2]||(e[2]=s('<h1 id="伪指令" tabindex="-1">伪指令 <a class="header-anchor" href="#伪指令" aria-label="Permalink to &quot;伪指令&quot;">​</a></h1><div class="epigraph"><p>汇编器把 `li`、`mv`、`csrr` 展开成一条或几条真实编码；硬件只看见 RV32I 与 CSR 指令，没有额外的 opcode。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume I 整理</footer></div><p>上一课<a href="/cs/riscv-csr-ecall">RISC-V CSR 与 ecall</a>把真实系统指令钉进 ISA。<a href="/cs/riscv-int-isa">整数指令</a>已声明 <code>li</code>/<code>mv</code> 是合成。本课不重讲 <code>ecall</code> 陷阱，也不从宏汇编语言另起。缺口是：程序员写的助记符与硬件执行的编码不是一一对应。后课寄存器堆只对<strong>真实</strong>的 <code>rs1</code>/<code>rs2</code>/<code>rd</code> 接线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>mv rd, rs</code> → <code>addi rd, rs, 0</code>。<code>li</code> 按常数宽度变成 <code>addi</code> 或 <code>lui</code>+<code>addi</code>。<code>nop</code> → <code>addi x0, x0, 0</code>。<code>csrr rd, csr</code> → <code>csrrs rd, csr, x0</code>。<code>j</code>/<code>jr</code>/<code>ret</code> 是 <code>jal</code>/<code>jalr</code> 的缺省寄存器写法。缺口不是新的数据通路，而是汇编器边界：反汇编可能看到展开后的真指令。</p><p>硬件没有 <code>li</code> 单元。把伪指令当 ALU 功能，单周期图会多出不存在的 MUX。</p><p><span class="marginnote"><code>nop</code> 的真身是 <code>addi x0, x0, 0</code>：x0 在 RISC-V 里永远读出 0，写了也白写，所以这条加法什么都不改，正好当「占位等待」用。初学者容易以为 CPU 里有专门的 nop 电路，其实它就是最普通的加法指令。</span></p><h3 id="伪指令不是微码" tabindex="-1">伪指令不是微码 <a class="header-anchor" href="#伪指令不是微码" aria-label="Permalink to &quot;伪指令不是微码&quot;">​</a></h3><p>CISC 微码在芯片内把复杂指令拆成内部步骤。RISC-V 伪指令在<strong>汇编时</strong>拆成程序员可见的真指令，每条仍一拍（或多拍取指）按 ISA 执行。两者都「拆」，层不同。</p><p><span class="marginnote">官方手册列出伪指令表。Patterson/Hennessy 用 <code>li</code>/<code>mv</code> 写例子。本课不把链接器的 <code>call</code> 远跳完整重定位写完，那是调用约定与链接课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列常用展开，核对字段仍落在上一课的格式里。宽立即数两拍：先 <code>lui</code> 高 20 位，再 <code>addi</code> 低 12 位，注意符号扩展对高位的借位调整。</p>',12)),(c(),i(t,null,{default:a(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASM%5B%22%E5%8A%A9%E8%AE%B0%E7%AC%A6%20li%20%2F%20mv%20%2F%20csrr%22%5D%20--%3E%20EXP%5B%22%E6%B1%87%E7%BC%96%E5%99%A8%E5%B1%95%E5%BC%80%22%5D%0A%20%20EXP%20--%3E%20REAL%5B%22%E7%9C%9F%E5%AE%9E%20RV32I%20%E6%88%96%20CSR%20%E7%BC%96%E7%A0%81%22%5D%0A%20%20REAL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%E7%AB%AF%E5%8F%A3%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=d("h2",{id:"机制",tabindex:"-1"},[o("机制 "),d("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=d("p",null,[o("展开之后，多数整数指令仍是两读一写：两个源寄存器（或一个源加立即数）、一个目的。这正是"),d("a",{href:"/cs/register-file"},"寄存器堆"),o("要提供的端口。"),d("code",null,"jal"),o(" 写 "),d("code",null,"rd"),o("、读 PC，稍有不同，仍是堆上的写口。CSR 指令多一个 CSR 口，通用堆端口不变。")],-1)),(c(),i(t,null,{default:a(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20LI%5B%22li%20rd%20%E5%B8%B8%E6%95%B0%22%5D%20--%3E%20Q%7B%22%E5%B8%B8%E6%95%B0%E5%A4%9A%E5%AE%BD%3F%22%7D%0A%20%20Q%20--%3E%7C%2212%20%E4%BD%8D%E6%9C%89%E7%AC%A6%E5%8F%B7%E4%BB%A5%E5%86%85%22%7C%20ONE%5B%22%E4%B8%80%E6%9D%A1%20addi%20rd%20x0%20%E5%B8%B8%E6%95%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9B%B4%E5%AE%BD%22%7C%20L1%5B%22lui%20rd%20%E8%A3%85%E9%AB%98%2020%20%E4%BD%8D%22%5D%0A%20%20L1%20--%3E%20L2%5B%22addi%20rd%20rd%20%E4%BD%8E%2012%20%E4%BD%8D%22%5D%0A%20%20L2%20--%3E%20ADJ%5B%22%E4%BD%8E%2012%20%E4%BD%8D%E7%AC%A6%E5%8F%B7%E4%B8%BA%201%20%E6%97%B6%E9%AB%98%2020%20%E4%BD%8D%E5%85%88%E8%A1%A5%E5%8A%A0%201%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s('<p><span class="marginnote">上图回答「<code>li</code> 什么时候变两条」：代入数字看，<code>li a0, 5</code> 一条 <code>addi a0, x0, 5</code> 就够；<code>li a0, 0x12345</code> 超出 12 位，就得 <code>lui a0, 0x12</code> 再 <code>addi a0, a0, 0x345</code> 两条拼起来。</span></p><p><span class="marginnote">初学者容易以为伪指令在硬件里也保留名字。实际上反汇编器 dump 出来的只有 <code>addi</code>/<code>lui</code>/<code>csrrs</code> 这些真编码——<code>li</code>、<code>mv</code>、<code>ret</code> 在 .o 文件里已不存在，只是汇编文本层的缩写。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把编译器优化、不把 <code>.macro</code> 用户宏当 ISA。压缩指令是另一编码，不是伪指令。</p><p>后课默认：谈到硬件，只存在真指令；助记符已展开。下一课实现 32×32 的多口堆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>伪指令是汇编展开，无新 opcode。</li><li><code>li</code>/<code>mv</code>/<code>nop</code>/<code>csrr</code>/<code>ret</code> 都落成已有指令。</li><li>硬件端口按真指令的两读一写来做。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V ISA Manual, Vol. I。</li></ul>',7))])}const _=n(A,[["render",B]]);export{f as __pageData,_ as default};
